-- 网安242班 模拟学习数据（教师端验证用）
-- 由 scripts 生成，随机种子 20260808，结果可复现。
--
-- 用途：让教师端「教学分析」在 242 班上有完整可验证的数据
--       （知识点错误分布饼图、知识点详情、AI 分析、学生画像）。
--
-- 【重要】这是模拟数据，不是真实学生操作产生的记录。
--   - 所有主键以 'sim242-' 开头，可整体清除，不影响其它数据
--   - learning_event.source 写成 'ai-agent-service'（生产来源），
--     因此画像与能力成长会把它当作真实证据纳入统计。
--     如果你希望它被画像排除，把 source 改成 'showcase-seed' 再执行。
--
-- 覆盖课程：SQL注入攻击(course_id=1, 7个知识点) / XSS与CSRF攻击(course_id=2, 5个知识点)
--
-- 数据规模：
--   训练会话 254 个
--   生成题 254 道 | 作答记录 313 条（含重做）
--   学生 31 人（教学班 5 / 行政班 8）
--   时间跨度 2026-07-18 ~ 2026-08-05
--
-- 可重复执行：每次先删除 'sim242-' 前缀数据再重新写入。

START TRANSACTION;

-- 前置条件：教师端「教学分析」的知识点风险查询里有
--   INNER JOIN teaching_class_course ON teaching_class_id AND course_id
-- 教学班没安排课程时，即使学生作答数据齐全，饼图也会是空的。
-- 242 班原本一门课都没关联，这里补上与 232 班一致的三门。
SELECT * FROM (
  SELECT 5 AS a, 1 AS b, 1 AS c, '2026-07-18' AS d, '2026-08-15' AS e, NOW(6) AS f, NOW(6) AS g
  UNION ALL SELECT 5, 2, 2, '2026-08-16', '2026-09-10', NOW(6), NOW(6)
  UNION ALL SELECT 5, 3, 3, '2026-09-11', '2026-10-08', NOW(6), NOW(6)
) AS src
WHERE NOT EXISTS (
  SELECT 1 FROM `userservice`.`teaching_class_course` t
  WHERE t.`teaching_class_id` = src.a AND t.`course_id` = src.b
);

-- XSS/CSRF 课程专属知识点：平台默认只播种 8 个（101/102/201/301/401/402/501/601），
-- 其中属于本课程的只有 201 和 301，饼图只有两块太单薄，这里补齐到 5 个。
-- 用 ON DUPLICATE KEY UPDATE 保证可重复执行，也不会被应用启动时的默认播种覆盖。
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `category`=VALUES(`category`),
  `description`=VALUES(`description`), `difficulty_level`=VALUES(`difficulty_level`);

ON DUPLICATE KEY UPDATE `relevance_weight`=VALUES(`relevance_weight`);

DELETE FROM `seclab_profile`.`learning_event`              WHERE `event_id` LIKE 'sim242-%';
DELETE FROM `seclab_profile`.`generated_question_attempt`  WHERE `attempt_id` LIKE 'sim242-%';
DELETE FROM `seclab_profile`.`question_knowledge_point`    WHERE `generated_question_id` LIKE 'sim242-%';
DELETE FROM `seclab_profile`.`generated_question`          WHERE `generated_question_id` LIKE 'sim242-%';
DELETE FROM `seclab_profile`.`training_session`            WHERE `training_session_id` LIKE 'sim242-%';






COMMIT;
