  ('sim242-att-0003', 'sim242-ts-0002', 'sim242-q-0002', 93, '"可以用 Tab 键代替空格。服务端再把 Tab 也加进黑名单就行了。"', 0, 47.6, 231, '2026-07-30 13:43:00'),
