  ('sim242-att-0051', 'sim242-ts-0038', 'sim242-q-0038', 120, '"检查文件后缀名就可以了，只允许 jpg 和 png 后缀。"', 0, 60.8, 61, '2026-07-23 00:22:00'),
  ('sim242-att-0052', 'sim242-ts-0039', 'sim242-q-0039', 122, '"把上传的文件改名就行了，改了名就执行不了。"', 0, 57.37, 165, '2026-07-27 15:39:00'),
  ('sim242-att-0053', 'sim242-ts-0040', 'sim242-q-0040', 92, '"递增 ORDER BY 的序号，首次报错说明超出了列数范围，所以列数等于报错序号减一。"', 1, 86.61, 210, '2026-07-28 22:05:00'),
  ('sim242-att-0054', 'sim242-ts-0041', 'sim242-q-0041', 93, '"递增 ORDER BY 的序号，首次报错说明超出了列数范围，所以列数等于报错序号减一。"', 1, 92.06, 88, '2026-07-22 18:03:00'),
  ('sim242-att-0055', 'sim242-ts-0042', 'sim242-q-0042', 94, '"ORDER BY 1、2、3 依次试，假设 ORDER BY 5 报错而 4 正常，那原查询就是 4 列，然后 UNION SELECT NULL,NULL,NULL,NULL 验证。"', 1, 98.57, 144, '2026-07-23 17:43:00'),
  ('sim242-att-0056', 'sim242-ts-0043', 'sim242-q-0043', 96, '"用 ORDER BY 排序看看结果有没有变化，变了就说明列数对。"', 0, 40.32, 238, '2026-08-04 17:48:00'),
  ('sim242-att-0057', 'sim242-ts-0043', 'sim242-q-0043', 96, '"递增 ORDER BY 的序号，首次报错说明超出了列数范围，所以列数等于报错序号减一。"', 1, 83.22, 236, '2026-08-05 21:15:00'),
  ('sim242-att-0058', 'sim242-ts-0044', 'sim242-q-0044', 99, '"用 ORDER BY 排序看看结果有没有变化，变了就说明列数对。"', 0, 38.63, 288, '2026-08-03 09:58:00'),
  ('sim242-att-0059', 'sim242-ts-0045', 'sim242-q-0045', 101, '"ORDER BY 1、2、3 依次试，假设 ORDER BY 5 报错而 4 正常，那原查询就是 4 列，然后 UNION SELECT NULL,NULL,NULL,NULL 验证。"', 1, 90.95, 133, '2026-07-26 21:39:00'),
  ('sim242-att-0060', 'sim242-ts-0046', 'sim242-q-0046', 102, '"直接用 UNION SELECT 1,2,3 一个个试，不报错就是对的。"', 0, 46.6, 289, '2026-08-05 16:33:00'),
  ('sim242-att-0061', 'sim242-ts-0046', 'sim242-q-0046', 102, '"递增 ORDER BY 的序号，首次报错说明超出了列数范围，所以列数等于报错序号减一。"', 1, 84.92, 223, '2026-08-09 19:42:00'),
  ('sim242-att-0062', 'sim242-ts-0047', 'sim242-q-0047', 103, '"ORDER BY 1、2、3 依次试，假设 ORDER BY 5 报错而 4 正常，那原查询就是 4 列，然后 UNION SELECT NULL,NULL,NULL,NULL 验证。"', 1, 89.14, 184, '2026-07-20 15:07:00'),
