  ('sim242-att-0064', 'sim242-ts-0049', 'sim242-q-0049', 106, '"从 ORDER BY 1 开始往上试，一直到某个数字开始报错，那个数字减一就是列数。再用 UNION SELECT NULL 补齐同样列数验证一下。"', 1, 98.18, 193, '2026-08-03 16:50:00'),
