  ('sim242-evt-0009', 101, 8, 1, 4, 1, 'QUESTION_SUBMIT', '2026-07-25 13:10:00', '{"score": 48.95, "answer": "把空格过滤掉就安全了，攻击者没有空格就没法拼命令。", "isCorrect": false, "knowledgePointId": 401, "generatedQuestionId": "sim242-q-0007"}', 'ai-agent-service', 'sim242-req-0009'),
