  ('sim242-evt-0170', 92, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-08-01 21:29:00', '{"score": 51.72, "answer": "只说了 HttpOnly 保护 Cookie，没提 CSP 也没说防不住什么。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0139"}', 'ai-agent-service', 'sim242-req-0170'),
  ('sim242-evt-0171', 93, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-08-05 10:27:00', '{"score": 45.24, "answer": "只说了 HttpOnly 保护 Cookie，没提 CSP 也没说防不住什么。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0140"}', 'ai-agent-service', 'sim242-req-0171'),
  ('sim242-evt-0172', 93, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-08-08 14:48:00', '{"score": 86.24, "answer": "HttpOnly 防的是 Cookie 被脚本读走，XSS 本身还在。CSP 可以挡掉外部脚本和内联脚本，但配置不严就没用。两者都是补充，不能代替编码。", "isCorrect": true, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0140", "retry": true}', 'ai-agent-service', 'sim242-req-0172'),
  ('sim242-evt-0173', 94, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-30 10:23:00', '{"score": 84.68, "answer": "HttpOnly 只保护 Cookie 这一项，攻击者仍可用受害者身份发起请求。CSP 需要严格禁用 unsafe-inline 才有意义。真正的修复是按输出上下文编码。", "isCorrect": true, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0141"}', 'ai-agent-service', 'sim242-req-0173'),
  ('sim242-evt-0174', 95, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-27 20:24:00', '{"score": 97.27, "answer": "不能。HttpOnly 只是让 document.cookie 读不到，攻击者照样能用 XSS 发请求、改页面、钓鱼。CSP 能限制脚本来源，但写了 unsafe-inline 就形同虚设，根本还是要做输出编码。", "isCorrect": true, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0142"}', 'ai-agent-service', 'sim242-req-0174'),
  ('sim242-evt-0175', 96, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-29 18:22:00', '{"score": 67.39, "answer": "HttpOnly 能阻止 XSS 脚本执行。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0143"}', 'ai-agent-service', 'sim242-req-0175'),
  ('sim242-evt-0176', 97, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-27 11:32:00', '{"score": 65.76, "answer": "只说了 HttpOnly 保护 Cookie，没提 CSP 也没说防不住什么。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0144"}', 'ai-agent-service', 'sim242-req-0176'),
  ('sim242-evt-0177', 97, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-30 12:26:00', '{"score": 60.03, "answer": "配置了 CSP 就完全不会有 XSS 了。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0144", "retry": true}', 'ai-agent-service', 'sim242-req-0177'),
  ('sim242-evt-0178', 98, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-30 11:15:00', '{"score": 45.11, "answer": "开了 HttpOnly 就安全了，脚本读不到 Cookie 就没法攻击。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0145"}', 'ai-agent-service', 'sim242-req-0178'),
  ('sim242-evt-0179', 98, 8, 2, 2, 3, 'QUESTION_SUBMIT', '2026-07-31 14:00:00', '{"score": 58.42, "answer": "只说了 HttpOnly 保护 Cookie，没提 CSP 也没说防不住什么。", "isCorrect": false, "knowledgePointId": 203, "generatedQuestionId": "sim242-q-0145", "retry": true}', 'ai-agent-service', 'sim242-req-0179'),
